"""Pydantic request/response schemas.

Responses are built as plain dicts in the service layer; request bodies are
validated here. Nothing in any response schema can carry a password hash or
a secret token (tokens are only ever returned once, at creation/login).
"""
from __future__ import annotations

import re
from typing import Literal, Optional

from pydantic import BaseModel, Field, field_validator

USERNAME_RE = re.compile(r"^[A-Za-z0-9_.-]{3,32}$")


class RegisterRequest(BaseModel):
    username: str = Field(min_length=3, max_length=32)
    password: str = Field(min_length=1, max_length=256)

    @field_validator("username")
    @classmethod
    def _username_shape(cls, v: str) -> str:
        if not USERNAME_RE.match(v):
            raise ValueError("username may contain only letters, digits, '_', '.', '-'")
        return v


class LoginRequest(BaseModel):
    username: str = Field(min_length=1, max_length=32)
    password: str = Field(min_length=1, max_length=256)


class CreateOrgRequest(BaseModel):
    name: str = Field(min_length=1, max_length=64)


class CreateInviteRequest(BaseModel):
    username: str = Field(min_length=3, max_length=32)
    role: Literal["admin", "member"]


class RevokeInviteRequest(BaseModel):
    # Token travels in the body (not the URL path) so it never appears in
    # reverse-proxy/access log lines.
    token: str = Field(min_length=8, max_length=128)


class AcceptInviteRequest(BaseModel):
    token: str = Field(min_length=8, max_length=128)


class UpdateMemberRequest(BaseModel):
    role: Optional[Literal["admin", "member"]] = None
    status: Optional[Literal["active", "disabled"]] = None


class CreateDelegationRequest(BaseModel):
    # strict int: floats / strings / booleans are 422, not silently coerced.
    user_id: int
    duration_seconds: int = Field(ge=60, le=86400, strict=True)

"""Stable JSON error envelope.

Every error response has the shape::

    {"error": {"code": "<stable_machine_code>", "message": "<human text>"}}

Error codes are part of the API contract and never expose internal details
such as whether an organization exists (non-members get ``forbidden`` both
when the org is missing and when they lack access).
"""
from __future__ import annotations

from fastapi import Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException


class ApiError(Exception):
    def __init__(self, status_code: int, code: str, message: str):
        super().__init__(message)
        self.status_code = status_code
        self.code = code
        self.message = message


# Common shortcuts ---------------------------------------------------------

def unauthorized(message: str = "authentication required") -> ApiError:
    return ApiError(401, "unauthorized", message)


def forbidden(message: str = "forbidden") -> ApiError:
    # Deliberately identical wording regardless of org existence/membership.
    return ApiError(403, "forbidden", message)


def not_found(code: str = "not_found", message: str = "not found") -> ApiError:
    return ApiError(404, code, message)


def conflict(code: str, message: str) -> ApiError:
    return ApiError(409, code, message)


def install_exception_handlers(app) -> None:
    @app.exception_handler(ApiError)
    async def _api_error(_: Request, exc: ApiError) -> JSONResponse:
        return JSONResponse(
            status_code=exc.status_code,
            content={"error": {"code": exc.code, "message": exc.message}},
        )

    @app.exception_handler(RequestValidationError)
    async def _validation_error(_: Request, exc: RequestValidationError) -> JSONResponse:
        return JSONResponse(
            status_code=422,
            content={"error": {"code": "validation_error", "message": "invalid request"}},
        )

    @app.exception_handler(StarletteHTTPException)
    async def _http_error(_: Request, exc: StarletteHTTPException) -> JSONResponse:
        # Normalize framework 404/405/etc. into the stable JSON envelope.
        if exc.status_code == 404:
            code, message = "not_found", "not found"
        elif exc.status_code == 405:
            code, message = "method_not_allowed", "method not allowed"
        else:
            code, message = "error", "error"
        return JSONResponse(
            status_code=exc.status_code,
            content={"error": {"code": code, "message": message}},
        )

    @app.exception_handler(Exception)
    async def _unexpected(_: Request, exc: Exception) -> JSONResponse:  # pragma: no cover
        # Do not leak internals; never echo tokens or passwords.
        return JSONResponse(
            status_code=500,
            content={"error": {"code": "internal_error", "message": "internal error"}},
        )

"""Test fixtures: a real uvicorn subprocess with a throwaway SQLite file.

Using a real process (instead of FastAPI's in-process test client) lets the
suite exercise true cross-thread HTTP concurrency, session behaviour and a
full process restart with on-disk persistence.
"""
from __future__ import annotations

import itertools
import os
import socket
import sqlite3
import subprocess
import sys
import time
import uuid
from pathlib import Path

import httpx
import pytest

REPO_ROOT = Path(__file__).resolve().parent.parent


def _free_port() -> int:
    s = socket.socket()
    s.bind(("127.0.0.1", 0))
    port = s.getsockname()[1]
    s.close()
    return port


class Server:
    def __init__(self, name: str = "default") -> None:
        self.tmp = Path(os.environ.get("TEST_TMP", "/tmp/team-access-tests")) / name
        self.tmp.mkdir(parents=True, exist_ok=True)
        self.db_path = self.tmp / "test.db"
        self.key_path = self.tmp / "secret.key"
        self.log_path = self.tmp / "server.log"
        for p in (self.db_path, self.key_path, self.log_path,
                  Path(str(self.db_path) + "-wal"), Path(str(self.db_path) + "-shm")):
            p.unlink(missing_ok=True)
        self.port = _free_port()
        self.base_url = f"http://127.0.0.1:{self.port}"
        self.proc: subprocess.Popen | None = None

    def _env(self) -> dict[str, str]:
        env = os.environ.copy()
        env["APP_DB_PATH"] = str(self.db_path)
        env["APP_SECRET_KEY_FILE"] = str(self.key_path)
        env["APP_INVITE_TTL"] = "86400"
        return env

    def start(self) -> None:
        log = open(self.log_path, "ab")
        self.proc = subprocess.Popen(
            [sys.executable, "-m", "uvicorn", "app.main:app",
             "--host", "127.0.0.1", "--port", str(self.port)],
            cwd=REPO_ROOT, env=self._env(), stdout=log, stderr=subprocess.STDOUT,
        )
        deadline = time.time() + 30
        while time.time() < deadline:
            if self.proc.poll() is not None:
                raise RuntimeError(f"server exited early; log:\n{self.log_path.read_text()}")
            try:
                r = httpx.get(f"{self.base_url}/health", timeout=1)
                if r.status_code == 200:
                    return
            except httpx.TransportError:
                time.sleep(0.1)
        raise RuntimeError("server did not become ready")

    def stop(self) -> None:
        if self.proc is not None and self.proc.poll() is None:
            self.proc.terminate()
            try:
                self.proc.wait(timeout=10)
            except subprocess.TimeoutExpired:
                self.proc.kill()
                self.proc.wait(timeout=10)
        self.proc = None

    def restart(self) -> None:
        self.stop()
        time.sleep(0.3)
        self.start()

    def sqlite(self) -> sqlite3.Connection:
        conn = sqlite3.connect(str(self.db_path), timeout=30)
        conn.row_factory = sqlite3.Row
        return conn


class Api:
    """Thin HTTP helper."""

    def __init__(self, base_url: str):
        self.base_url = base_url
        self._counter = itertools.count(1)

    def client(self) -> httpx.Client:
        return httpx.Client(base_url=self.base_url, timeout=30)

    def unique(self, prefix: str = "u") -> str:
        # Globally unique across tests/runs: the server DB is session scoped.
        return f"{prefix}_{uuid.uuid4().hex[:16]}"

    def request(self, method: str, path: str, *, token: str | None = None, **kwargs):
        headers = kwargs.pop("headers", {}) or {}
        if token:
            headers["Authorization"] = f"Bearer {token}"
        with self.client() as c:
            return c.request(method, path, headers=headers, **kwargs)

    # -- sugar -------------------------------------------------------------
    def register(self, username: str, password: str = "Passw0rd!"):
        return self.request("POST", "/auth/register", json={"username": username, "password": password})

    def login(self, username: str, password: str = "Passw0rd!"):
        return self.request("POST", "/auth/login", json={"username": username, "password": password})

    def token_for(self, username: str, password: str = "Passw0rd!") -> str:
        r = self.login(username, password)
        assert r.status_code == 200, r.text
        return r.json()["token"]

    def new_user(self) -> tuple[str, str]:
        u = self.unique()
        r = self.register(u)
        assert r.status_code == 201, r.text
        return u, self.token_for(u)


@pytest.fixture(scope="session")
def server():
    srv = Server()
    srv.start()
    yield srv
    srv.stop()


@pytest.fixture()
def api(server) -> Api:
    return Api(server.base_url)


@pytest.fixture()
def db(server) -> sqlite3.Connection:
    """Direct SQLite handle for test-only assertions / state manipulation."""
    conn = server.sqlite()
    yield conn
    conn.close()


@pytest.fixture()
def make_server():
    """Factory for an isolated server instance (used by restart tests)."""
    created: list[Server] = []

    def _make(name: str) -> Server:
        srv = Server(name=f"iso-{name}-{os.getpid()}")
        srv.start()
        created.append(srv)
        return srv

    yield _make
    for srv in created:
        srv.stop()

